2|//! executes the returned existing bank operation; it contains no retry policy.
3|use serde::{Deserialize, Serialize};
4|use serde_json::{json, Value};
5|
6|#[derive(Default, Deserialize, Serialize)]
7|struct State {
8|    start: f64,
9|    before: f64,
10|    rounds: u32,
11|    phase: String,
12|}
13|
14|pub fn step(input: &Value) -> Value {
15|    let count = input["count"].as_f64().unwrap_or(0.0);
16|    let target = input["target"].as_f64().unwrap_or(0.0);
17|    let mut s: State = serde_json::from_value(input["state"].clone()).unwrap_or(State {
18|        start: count,
19|        ..Default::default()
20|    });
21|    let full = input["full"].as_bool().unwrap_or(false);
22|    let ok = input["ok"].as_bool().unwrap_or(false);
23|    if s.phase == "op" && !ok {
24|        return json!({"kind":"done", "value":count-s.start});
25|    }
26|    let fallback = s.phase == "x" && !(ok && count > s.before);
27|    if !fallback {
28|        if s.rounds >= 40 || count >= target || full {
29|            return json!({"kind":"done", "value":count-s.start});
30|        }
31|        s.rounds += 1;
32|        s.before = count;
33|    }
34|    let need = target - s.before;
35|    if need <= 0.0 {
36|        return json!({"kind":"done", "value":count-s.start});
37|    }
38|    if need > 10.0 && !fallback {
39|        s.phase = "x".into();
40|        return json!({"kind":"x", "count":need, "state":s});
41|    }
42|    s.phase = "op".into();
43|    let op = if need >= 10.0 {
44|        "Withdraw-10"
45|    } else if need >= 5.0 {
46|        "Withdraw-5"
47|    } else {
48|        "Withdraw-1"
49|    };
50|    json!({"kind":"op", "op":op, "before":s.before, "state":s})
51|}
52|
53|#[cfg(test)]
54|mod tests {
55|    use super::*;
56|    #[test]
57|    fn x_then_fallback_then_exact_remainder() {
58|        let x = step(&json!({"count":2,"target":22}));
59|        assert_eq!(x["kind"], "x");
60|        assert_eq!(x["count"], 20.0);
61|        let op = step(&json!({"state":x["state"],"count":2,"target":22,"ok":false}));
62|        assert_eq!(op["op"], "Withdraw-10");
63|        let rest = step(&json!({"state":op["state"],"count":12,"target":22,"ok":true}));
64|        assert_eq!(rest["op"], "Withdraw-10");
65|        let done = step(&json!({"state":rest["state"],"count":22,"target":22,"ok":true}));
66|        assert_eq!(done["value"], 20.0);
67|    }
68|    #[test]
69|    fn no_progress_and_full_inventory_stop() {
70|        let op = step(&json!({"count":0,"target":5}));
71|        assert_eq!(op["op"], "Withdraw-5");
72|        assert_eq!(
73|            step(&json!({"state":op["state"],"count":0,"target":5,"ok":false}))["kind"],
74|            "done"
75|        );
76|        assert_eq!(
77|            step(&json!({"count":2,"target":22,"full":true}))["value"],
78|            0.0
79|        );
80|    }
81|}
