{"content": "1|//! Process RSS / CPU sample for live harnesses and the panel resource card.
2|//!
3|//! [`sample_process`] first field is lifetime peak resident:
4|//! - macos/linux: `ru_maxrss` (bytes / KiB→bytes)
5|//! - windows: `PeakWorkingSetSize` from `GetProcessMemoryInfo`
6|//!
7|//! CPU second field is cumulative process user+kernel seconds (panel delta).
8|//! Failure sentinel remains `(0, 0.0)` for public tuple compatibility.
9|
10|pub fn rss_bytes_from_ru_maxrss(raw: i64) -> u64 {
11|    if raw < 0 {
12|        return 0;
13|    }
14|    let n = raw as u64;
15|    #[cfg(target_os = "linux")]
16|    {
17|        n.saturating_mul(1024)
18|    }
19|    #[cfg(target_os = "macos")]
20|    {
21|        n
22|    }
23|    #[cfg(not(any(target_os = "macos", target_os = "linux")))]
24|    {
25|        let _ = n;
26|        0
27|    }
28|}
29|
30|/// Convert GetProcessTimes user/kernel `FILETIME` parts to seconds.
31|/// Those values are **CPU durations** in 100 ns units (not wall time since 1601).
32|/// Pure; factored for unit tests without calling the OS.
33|#[cfg(windows)]
34|pub(crate) fn filetime_parts_to_seconds(high: u32, low: u32) -> f64 {
35|    let ticks = ((high as u64) << 32) | (low as u64);
36|    ticks as f64 / 10_000_000.0
37|}
38|
39|/// Combine Windows peak-resident and CPU samples into the public tuple.
40|/// If **either** sampler fails (`None`), return the joint failure sentinel
41|/// `(0, 0.0)` so panel treats the whole sample as Error (not mixed zeros).
42|/// Pure and OS-agnostic so Mac/Linux can unit-test mixed failure without
43|/// synthetic Win32 API failures. Wired only into the Windows `sample_process`.
44|#[cfg(any(windows, test))]
45|pub(crate) fn combine_windows_sample(peak: Option<u64>, cpu: Option<f64>) -> (u64, f64) {
46|    match (peak, cpu) {
47|        (Some(p), Some(c)) => (p, c),
48|        _ => (0, 0.0),
49|    }
50|}
51|
52|/// Map a resident size to `Option`, never `Some(0)`.
53|#[cfg(windows)]
54|fn nonzero_resident(n: usize) -> Option<u64> {
55|    let n = n as u64;
56|    if n == 0 {
57|        None
58|    } else {
59|        Some(n)
60|    }
61|}
62|
63|/// Raw `(WorkingSetSize, PeakWorkingSetSize)` when `GetProcessMemoryInfo` succeeds.
64|/// Callers map zeros to `None` / sentinel — do not treat a successful zero as real.
65|#[cfg(windows)]
66|fn windows_memory_counters() -> Option<(usize, usize)> {
67|    use windows_sys::Win32::System::ProcessStatus::{
68|        GetProcessMemoryInfo, PROCESS_MEMORY_COUNTERS,
69|    };
70|    use windows_sys::Win32::System::Threading::GetCurrentProcess;
71|
72|    // GetCurrentProcess returns a pseudo-handle; do not CloseHandle it.
73|    unsafe {
74|        let mut pmc: PROCESS_MEMORY_COUNTERS = std::mem::zeroed();
75|        pmc.cb = std::mem::size_of::<PROCESS_MEMORY_COUNTERS>() as u32;
76|        let ok = GetProcessMemoryInfo(GetCurrentProcess(), &mut pmc, pmc.cb);
77|        if ok == 0 {
78|            return None;
79|        }
80|        Some((pmc.WorkingSetSize, pmc.PeakWorkingSetSize))
81|    }
82|}
83|
84|#[cfg(windows)]
85|fn windows_cpu_seconds_total() -> Option<f64> {
86|    windows_cpu_user_kernel().map(|(u, k)| u + k)
87|}
88|
89|#[cfg(windows)]
90|pub(crate) fn windows_cpu_user_kernel() -> Option<(f64, f64)> {
91|    use windows_sys::Win32::Foundation::FILETIME;
92|    use windows_sys::Win32::System::Threading::{GetCurrentProcess, GetProcessTimes};
93|
94|    // GetCurrentProcess pseudo-handle — do not close.
95|    unsafe {
96|        let mut creation: FILETIME = std::mem::zeroed();
97|        let mut exit: FILETIME = std::mem::zeroed();
98|        let mut kernel: FILETIME = std::mem::zeroed();
99|        let mut user: FILETIME = std::mem::zeroed();
100|        let ok = GetProcessTimes(
101|            GetCurrentProcess(),
102|            &mut creation,
103|            &mut exit,
104|            &mut kernel,
105|            &mut user,
106|        );
107|        if ok == 0 {
108|            return None;
109|        }
110|        let user_s = filetime_parts_to_seconds(user.dwHighDateTime, user.dwLowDateTime);
111|        let kernel_s = filetime_parts_to_seconds(kernel.dwHighDateTime, kernel.dwLowDateTime);
112|        Some((user_s, kernel_s))
113|    }
114|}
115|
116|pub fn sample_process() -> (u64, f64) {
117|    #[cfg(any(target_os = "macos", target_os = "linux"))]
118|    {
119|        let mut usage: libc::rusage = unsafe { std::mem::zeroed() };
120|        let rc = unsafe { libc::getrusage(libc::RUSAGE_SELF, &mut usage) };
121|        if rc != 0 {
122|            return (0, 0.0);
123|        }
124|        let rss = rss_bytes_from_ru_maxrss(usage.ru_maxrss);
125|        let cpu = usage.ru_utime.tv_sec as f64
126|            + usage.ru_utime.tv_usec as f64 / 1e6
127|            + usage.ru_stime.tv_sec as f64
128|            + usage.ru_stime.tv_usec as f64 / 1e6;
129|        (rss, cpu)
130|    }
131|    #[cfg(windows)]
132|    {
133|        // First field = PeakWorkingSetSize (lifetime peak WS).
134|        // Either sampler fail → full (0, 0.0) sentinel (panel joint check).
135|        let peak = windows_memory_counters().and_then(|(_, peak)| nonzero_resident(peak));
136|        let cpu = windows_cpu_seconds_total();
137|        combine_windows_sample(peak, cpu)
138|    }
139|    #[cfg(not(any(target_os = "macos", target_os = "linux", windows)))]
140|    {
141|        (0, 0.0)
142|    }
143|}
