145|/// Current resident set size in bytes.
146|///
147|/// Distinct from [`sample_process`]'s first field, which is lifetime peak
148|/// (`ru_maxrss` / Windows `PeakWorkingSetSize`). Returns `None` on unsupported
149|/// OS or sample failure — never `Some(0)`.
150|pub fn current_resident_bytes() -> Option<u64> {
151|    #[cfg(target_os = "macos")]
152|    {
153|        // libc::mach_task_self is deprecated in favor of mach2; stay on
154|        // libc with the rest of host-play and suppress the warn.
155|        #[allow(deprecated)]
156|        unsafe {
157|            let mut info: libc::mach_task_basic_info = std::mem::zeroed();
158|            let mut count = libc::MACH_TASK_BASIC_INFO_COUNT;
159|            let kr = libc::task_info(
160|                libc::mach_task_self(),
161|                libc::MACH_TASK_BASIC_INFO,
162|                &mut info as *mut _ as libc::task_info_t,
163|                &mut count,
164|            );
165|            if kr != libc::KERN_SUCCESS {
166|                return None;
167|            }
168|            let n = info.resident_size as u64;
169|            if n == 0 {
170|                None
171|            } else {
172|                Some(n)
173|            }
174|        }
175|    }
176|    #[cfg(target_os = "linux")]
177|    {
178|        let text = std::fs::read_to_string("/proc/self/statm").ok()?;
179|        let mut parts = text.split_whitespace();
180|        let _total_pages = parts.next()?;
181|        let resident_pages: u64 = parts.next()?.parse().ok()?;
182|        if resident_pages == 0 {
183|            return None;
184|        }
185|        let page = unsafe { libc::sysconf(libc::_SC_PAGESIZE) };
186|        if page <= 0 {
187|            return None;
188|        }
189|        Some(resident_pages.saturating_mul(page as u64))
190|    }
191|    #[cfg(windows)]
192|    {
193|        windows_memory_counters().and_then(|(current, _)| nonzero_resident(current))
194|    }
195|    #[cfg(not(any(target_os = "macos", target_os = "linux", windows)))]
196|    {
197|        None
198|    }
199|}
