201|/// Count unique ESTABLISHED TCP names in `lsof -nP -iTCP` stdout.
202|/// One socket can appear twice (reader + writer fd); the NAME column
203|/// (`host:port->host:port`) is the connection.
204|pub fn parse_lsof_established(stdout: &str) -> usize {
205|    use std::collections::HashSet;
206|    let mut names = HashSet::new();
207|    for line in stdout.lines() {
208|        if !line.contains("ESTABLISHED") {
209|            continue;
210|        }
211|        let Some(tcp) = line.find("TCP ") else {
212|            continue;
213|        };
214|        let rest = &line[tcp + 4..];
215|        if let Some(name) = rest.split_whitespace().next() {
216|            names.insert(name);
217|        }
218|    }
219|    names.len()
220|}
