222|/// Established TCP from this pid to `host:port`, via `lsof`. `None` if
223|/// `lsof` is missing. Empty match is `Some(0)` (`lsof` exits 1).
224|///
225|/// **Windows:** no TCP-count backend in this hop (`lsof` is unix-only).
226|/// Always `None` — do not shell out or fabricate zero.
227|pub fn count_tcp_to(host: &str, port: u16) -> Option<usize> {
228|    #[cfg(windows)]
229|    {
230|        let _ = (host, port);
231|        None
232|    }
233|    #[cfg(not(windows))]
234|    {
235|        let pid = std::process::id().to_string();
236|        let spec = format!("-iTCP@{host}:{port}");
237|        let output = std::process::Command::new("lsof")
238|            .args(["-nP", "-a", "-p", &pid, &spec])
239|            .output()
240|            .ok()?;
241|        Some(parse_lsof_established(&String::from_utf8_lossy(
242|            &output.stdout,
243|        )))
244|    }
