{"content": "1|//! Passive per-isolate accounting. Snapshot gauges cover queued and decoding
2|//! buffers, including capacity; no extra channel messages or JS probes.
3|use std::sync::{
4|    atomic::{AtomicU64, Ordering::Relaxed},
5|    Arc,
6|};
7|#[derive(Default)]
8|pub struct Counters {
9|    pub bytes: AtomicU64,
10|    pub capacity: AtomicU64,
11|    pub peak_capacity: AtomicU64,
12|    pub heap_live: AtomicU64,
13|    pub heap_used: AtomicU64,
14|    pub heap_total: AtomicU64,
15|    pub heap_samples: AtomicU64,
16|    pub heap_updated_ms: AtomicU64,
17|    pub tick_count: AtomicU64,
18|    pub tick_ns: AtomicU64,
19|    pub tick_max_ns: AtomicU64,
20|}
21|impl Counters {
22|    pub fn snapshot(&self) -> serde_json::Value {
23|        serde_json::json!({"snapshot_inflight_bytes":self.bytes.load(Relaxed),
24|            "snapshot_inflight_capacity":self.capacity.load(Relaxed),
25|            "snapshot_peak_capacity":self.peak_capacity.load(Relaxed),
26|            "v8_live":self.heap_live.load(Relaxed),"v8_used_bytes":self.heap_used.load(Relaxed),"v8_total_bytes":self.heap_total.load(Relaxed),
27|            "v8_heap_samples":self.heap_samples.load(Relaxed),"v8_updated_ms":self.heap_updated_ms.load(Relaxed),
28|            "script_tick_count":self.tick_count.load(Relaxed),"script_tick_total_ns":self.tick_ns.load(Relaxed),
29|            "script_tick_max_ns":self.tick_max_ns.load(Relaxed)})
30|    }
31|    pub fn tick(&self, elapsed: std::time::Duration) {
32|        let ns = elapsed.as_nanos().min(u64::MAX as u128) as u64;
33|        self.tick_ns.fetch_add(ns, Relaxed);
34|        self.tick_max_ns.fetch_max(ns, Relaxed);
35|        self.tick_count.fetch_add(1, Relaxed);
36|    }
37|}
38|pub struct SnapshotLease {
39|    counters: Arc<Counters>,
40|    len: u64,
41|    capacity: u64,
42|}
43|impl SnapshotLease {
44|    pub fn new(counters: Arc<Counters>, len: usize, capacity: usize) -> Self {
45|        counters.bytes.fetch_add(len as u64, Relaxed);
46|        let current = counters.capacity.fetch_add(capacity as u64, Relaxed) + capacity as u64;
47|        counters.peak_capacity.fetch_max(current, Relaxed);
48|        Self {
49|            counters,
50|            len: len as u64,
51|            capacity: capacity as u64,
52|        }
53|    }
54|}
55|impl Drop for SnapshotLease {
56|    fn drop(&mut self) {
57|        self.counters.bytes.fetch_sub(self.len, Relaxed);
58|        self.counters.capacity.fetch_sub(self.capacity, Relaxed);
59|    }
60|}
61|#[cfg(test)]
62|mod tests {
63|    use super::*;
64|    #[test]
65|    fn thread_ownership_survives_handle_release_without_registry_retention() {
66|        let counters = registered();
67|        let weak = Arc::downgrade(&counters);
68|        let (tx, rx) = std::sync::mpsc::channel();
69|        let thread = std::thread::spawn(move || {
70|            let _owner = counters;
71|            rx.recv().unwrap();
72|        });
73|        assert!(weak.upgrade().is_some());
74|        tx.send(()).unwrap();
75|        thread.join().unwrap();
76|        assert!(weak.upgrade().is_none());
77|    }
78|    #[test]
79|    fn runtime_teardown_clears_heap_gauges() {
80|        let c = Arc::new(Counters::default());
81|        c.heap_live.store(1, Relaxed);
82|        c.heap_used.store(12, Relaxed);
83|        c.heap_total.store(16, Relaxed);
84|        drop(HeapLifetime(c.clone()));
85|        assert_eq!(c.heap_live.load(Relaxed), 0);
86|        assert_eq!(c.heap_used.load(Relaxed), 0);
87|        assert_eq!(c.heap_total.load(Relaxed), 0);
88|    }
89|    #[test]
90|    fn snapshot_lifetime_counts_capacity_and_releases_on_channel_drop() {
91|        let c = Arc::new(Counters::default());
92|        let (tx, rx) = std::sync::mpsc::channel();
93|        tx.send(SnapshotLease::new(c.clone(), 3, 16)).unwrap();
94|        tx.send(SnapshotLease::new(c.clone(), 5, 32)).unwrap();
95|        assert_eq!(c.bytes.load(Relaxed), 8);
96|        assert_eq!(c.capacity.load(Relaxed), 48);
97|        let consumed = rx.recv().unwrap();
98|        assert_eq!(c.capacity.load(Relaxed), 48);
99|        drop(consumed);
100|        assert_eq!(c.capacity.load(Relaxed), 32);
101|        drop(rx);
102|        assert_eq!(c.capacity.load(Relaxed), 0);
103|        assert!(tx.send(SnapshotLease::new(c.clone(), 1, 8)).is_err());
104|        assert_eq!(c.bytes.load(Relaxed), 0);
105|        assert_eq!(c.capacity.load(Relaxed), 0);
106|    }
