109|pub struct HeapLifetime(pub Arc<Counters>);
110|impl Drop for HeapLifetime {
111|    fn drop(&mut self) {
112|        self.0.heap_used.store(0, Relaxed);
113|        self.0.heap_total.store(0, Relaxed);
114|        self.0.heap_live.store(0, Relaxed);
115|    }
