118|static REGISTRY: std::sync::OnceLock<std::sync::Mutex<Vec<std::sync::Weak<Counters>>>> =
119|    std::sync::OnceLock::new();
120|pub fn registered() -> Arc<Counters> {
121|    let counters = Arc::new(Counters::default());
122|    let mut rows = REGISTRY.get_or_init(Default::default).lock().unwrap();
123|    rows.retain(|r| r.strong_count() > 0);
124|    rows.push(Arc::downgrade(&counters));
125|    counters
126|}
127|/// Includes detached isolate threads until their real resources are released.
128|/// Weak registration never keeps an isolate or its counters alive.
129|pub fn snapshots() -> Vec<serde_json::Value> {
130|    let mut rows = REGISTRY.get_or_init(Default::default).lock().unwrap();
131|    rows.retain(|r| r.strong_count() > 0);
132|    rows.iter()
133|        .filter_map(|r| r.upgrade())
134|        .map(|r| r.snapshot())
135|        .collect()
