2|//! descriptor payload sizes, not driver VRAM: exclude padding, pipelines,
3|//! bind groups, host UI resources, pending submissions and externally retained
4|//! views after their backend is dropped. Enable before constructing clients.
5|use std::sync::{
6|    atomic::{AtomicBool, AtomicU64, Ordering::Relaxed},
7|    Mutex,
8|};
9|use std::time::Instant;
10|static ENABLED: AtomicBool = AtomicBool::new(false);
11|pub fn enable() {
12|    ENABLED.store(true, Relaxed);
