14|#[derive(Clone, Copy, Default, Debug)]
15|pub struct GpuBytes {
16|    pub buffers: u64,
17|    pub textures: u64,
18|    pub peak: u64,
19|}
20|static GPU: Mutex<GpuBytes> = Mutex::new(GpuBytes {
21|    buffers: 0,
22|    textures: 0,
23|    peak: 0,
24|});
25|pub fn gpu_bytes() -> GpuBytes {
26|    *GPU.lock().unwrap()
27|}
28|pub struct Allocation {
29|    buffers: u64,
30|    textures: u64,
31|}
32|impl Allocation {
33|    pub fn new(buffers: u64, textures: u64) -> Self {
34|        let (buffers, textures) = if ENABLED.load(Relaxed) {
35|            (buffers, textures)
36|        } else {
37|            (0, 0)
38|        };
39|        if buffers + textures > 0 {
40|            let mut g = GPU.lock().unwrap();
41|            g.buffers += buffers;
42|            g.textures += textures;
43|            g.peak = g.peak.max(g.buffers + g.textures);
44|        }
45|        Self { buffers, textures }
46|    }
47|}
48|impl Drop for Allocation {
49|    fn drop(&mut self) {
50|        if self.buffers + self.textures > 0 {
51|            let mut g = GPU.lock().unwrap();
52|            g.buffers -= self.buffers;
53|            g.textures -= self.textures;
54|        }
55|    }
