57|/// Count every mip and array layer; current formats have 4-byte texels
58|/// (including Depth32Float). Unknown format sizes fail visibly in profiling.
59|pub fn texture_bytes(t: &wgpu::Texture) -> u64 {
60|    if !ENABLED.load(Relaxed) {
61|        return 0;
62|    }
63|    let bytes = t
64|        .format()
65|        .block_copy_size(None)
66|        .expect("profile: texture format size");
67|    let (bw, bh) = t.format().block_dimensions();
68|    (0..t.mip_level_count())
69|        .map(|m| {
70|            let w = (t.width() >> m).max(1).div_ceil(bw) as u64;
71|            let h = (t.height() >> m).max(1).div_ceil(bh) as u64;
72|            let layers = if t.dimension() == wgpu::TextureDimension::D3 {
73|                (t.depth_or_array_layers() >> m).max(1)
74|            } else {
75|                t.depth_or_array_layers()
76|            };
77|            w * h * layers as u64 * bytes as u64 * t.sample_count() as u64
78|        })
79|        .sum()
80|}
81|pub struct DurationCounter {
82|    count: AtomicU64,
83|    total: AtomicU64,
84|    max: AtomicU64,
85|}
86|impl DurationCounter {
87|    pub const fn new() -> Self {
88|        Self {
89|            count: AtomicU64::new(0),
90|            total: AtomicU64::new(0),
91|            max: AtomicU64::new(0),
92|        }
93|    }
94|    pub fn start(&'static self) -> Timer {
95|        Timer {
96|            counter: self,
97|            start: ENABLED.load(Relaxed).then(Instant::now),
98|        }
99|    }
100|    /// Cumulative (count,total nanoseconds,max nanoseconds); consumers can
101|    /// difference count/total between samples without resetting hot counters.
102|    pub fn read(&self) -> (u64, u64, u64) {
103|        (
104|            self.count.load(Relaxed),
105|            self.total.load(Relaxed),
106|            self.max.load(Relaxed),
107|        )
108|    }
109|}
110|pub struct Timer {
111|    counter: &'static DurationCounter,
112|    start: Option<Instant>,
113|}
114|impl Drop for Timer {
115|    fn drop(&mut self) {
116|        if let Some(start) = self.start {
117|            let ns = start.elapsed().as_nanos().min(u64::MAX as u128) as u64;
118|            self.counter.total.fetch_add(ns, Relaxed);
119|            self.counter.max.fetch_max(ns, Relaxed);
120|            self.counter.count.fetch_add(1, Relaxed);
121|        }
122|    }
123|}
