{"content": "1|//! Bounded, opt-in diagnostics for memory runs. Never drains application logs.
2|use serde_json::{json, Value};
3|use std::collections::{HashMap, VecDeque};
4|use std::sync::{Mutex, OnceLock};
5|use std::time::Instant;
6|
7|#[derive(Default)]
8|struct Slot {
9|    snapshot: Value,
10|    logs: VecDeque<String>,
11|    requests: VecDeque<String>,
12|    last_capture: Option<Instant>,
13|    sent_batches: u64,
14|    request_batches: u64,
15|}
16|static SLOTS: OnceLock<Mutex<HashMap<String, Slot>>> = OnceLock::new();
17|
18|pub(crate) fn enable(names: &[String]) {
19|    let _ = SLOTS.set(Mutex::new(
20|        names.iter().map(|n| (n.clone(), Slot::default())).collect(),
21|    ));
22|}
23|fn bounded_push(queue: &mut VecDeque<String>, text: &str) {
24|    if queue.len() == 32 {
25|        queue.pop_front();
26|    }
27|    queue.push_back(text.chars().take(512).collect());
28|}
29|pub(crate) fn logs(name: &str, lines: &[String]) {
30|    if lines.is_empty() {
31|        return;
32|    }
33|    let Some(all) = SLOTS.get() else { return };
34|    if let Some(slot) = all.lock().unwrap().get_mut(name) {
35|        for line in lines {
36|            bounded_push(&mut slot.logs, line)
37|        }
38|    }
39|}
40|pub(crate) fn requests(name: &str, reqs: &[script::shim::InteractReq]) {
41|    if reqs.is_empty() {
42|        return;
43|    }
44|    let Some(all) = SLOTS.get() else { return };
45|    if let Some(slot) = all.lock().unwrap().get_mut(name) {
46|        slot.request_batches += 1;
47|        for req in reqs {
48|            bounded_push(&mut slot.requests, &format!("{req:?}"))
49|        }
50|    }
51|}
52|pub(crate) fn sent(name: &str, wrote: bool) {
53|    let Some(all) = SLOTS.get() else { return };
54|    if wrote {
55|        if let Some(slot) = all.lock().unwrap().get_mut(name) {
56|            slot.sent_batches += 1;
57|        }
58|    }
59|}
60|pub(crate) fn frame(c: &client::client::Client, name: &str, hold: bool) {
61|    let Some(all) = SLOTS.get() else { return };
62|    let mut all = all.lock().unwrap();
63|    let Some(slot) = all.get_mut(name) else {
64|        return;
65|    };
66|    if slot
67|        .last_capture
68|        .is_some_and(|t| t.elapsed().as_millis() < 1000)
69|    {
70|        return;
71|    }
72|    let guards: Vec<_>=c.npc_ids.iter().take(c.npc_count.max(0) as usize).filter_map(|index| {
73|        let npc=c.npc.get(*index as usize)?.as_ref()?;
74|        let kind=c.cache.npcs.get(npc.r#type?)?;
75|        if kind.name != "Guard" {return None}
76|        Some(json!({"index":index,"type":npc.r#type,"x":c.map_build_base_x+npc.route_x[0],"z":c.map_build_base_z+npc.route_z[0],"face_entity":npc.face_entity,"animation":npc.primary_anim}))
77|    }).take(16).collect();
78|    slot.snapshot = json!({"client_tick":c.gens.player,"loop_cycle":c.loop_cycle,
79|        "xp":c.stat_xp.get(17),"hp":c.stat_effective_level.get(3),
80|        "position":crate::player_here_tile(c),"ingame":c.ingame,"scene_state":c.scene_state,
81|        "drawing":c.draw,"hold":hold,"animation":c.local_player.as_ref().map(|p|p.primary_anim),
82|        "spot_animation":c.local_player.as_ref().map(|p|p.spotanim_id),
83|        "spot_animation_start_cycle":c.local_player.as_ref().map(|p|p.spotanim_last_cycle),
84|        "face_entity":c.local_player.as_ref().map(|p|p.face_entity),
85|        "chat":c.chat_text.first(),"guards":guards});
86|    slot.last_capture = Some(Instant::now());
87|}
88|pub(crate) fn sample(name: &str) -> Value {
89|    let Some(all) = SLOTS.get() else {
90|        return Value::Null;
91|    };
92|    let all = all.lock().unwrap();
93|    let Some(slot) = all.get(name) else {
94|        return Value::Null;
95|    };
96|    // Detailed navigation history belongs to the excluded campaign capture hooks.
97|    json!({"client":slot.snapshot,"snapshot_age_ms":slot.last_capture.map(|t|t.elapsed().as_millis()),"recent_logs":slot.logs,"recent_requests":slot.requests,"recent_navigation":Value::Null,"request_batches":slot.request_batches,"sent_batches":slot.sent_batches})
98|}
99|#[cfg(test)]
100|mod tests {
101|    #[test]
102|    fn logs_remain_bounded_and_keep_latest_utf8_messages() {
103|        let mut queue = std::collections::VecDeque::new();
104|        for i in 0..100 {
105|            super::bounded_push(&mut queue, &format!("{i}:{}", "é".repeat(1024)));
106|        }
107|        assert_eq!(queue.len(), 32);
108|        assert!(queue.front().unwrap().starts_with("68:"));
109|        assert!(queue.back().unwrap().starts_with("99:"));
110|        assert!(queue.iter().all(|s| s.chars().count() == 512));
111|    }
112|}
