{"content": "1|//! Operator `HOME` / `$RS2B0T` for `~/.274bot` paths.
2|//!
3|//! Unit tests must not `set_var("HOME")`. That is process-global: a
4|//! parallel test (or a panic before restore) rewrites the operator's
5|//! panel prefs, catalog path, JS store, settings, and loadouts.
6|//! [`IsolatedEnv`] pins those lookups to a unique scratch on **this
7|//! thread only** and restores on drop.
8|//!
9|//! Production home reads use a tiny local Windows `USERPROFILE` adapter
10|//! (same rules as `client::operator_home`) so this crate stays free of a
11|//! production `client` dependency.
12|
13|use std::cell::RefCell;
14|use std::env;
15|use std::path::{Path, PathBuf};
16|use std::sync::atomic::{AtomicU64, Ordering};
17|
18|thread_local! {
19|    static HOME_OVERRIDE: RefCell<Option<PathBuf>> = const { RefCell::new(None) };
20|    static RS2B0T_OVERRIDE: RefCell<Option<Rs2b0tOverride>> = const { RefCell::new(None) };
21|    static THREAD_PIN: RefCell<Option<PathBuf>> = const { RefCell::new(None) };
22|}
23|
24|static SEQ: AtomicU64 = AtomicU64::new(0);
25|
26|#[derive(Clone)]
27|enum Rs2b0tOverride {
28|    Cleared,
29|    Set(PathBuf),
30|}
31|
32|/// Same shape as `client::operator_home` / `env::var("HOME")`. Kept local so
33|/// `script` does not take a production `client` dependency.
34|fn operator_home() -> Result<String, env::VarError> {
35|    operator_home_from(env::var("HOME"), || env::var("USERPROFILE"))
36|}
37|
38|fn operator_home_from(
39|    home: Result<String, env::VarError>,
40|    userprofile: impl FnOnce() -> Result<String, env::VarError>,
41|) -> Result<String, env::VarError> {
42|    #[cfg(windows)]
43|    {
44|        match home {
45|            Ok(h) => Ok(h),
46|            Err(_) => userprofile(),
47|        }
48|    }
49|    #[cfg(not(windows))]
50|    {
51|        let _ = userprofile;
52|        home
53|    }
54|}
55|
56|/// `$HOME`, or this thread's [`IsolatedEnv`] scratch when a test pinned one.
57|/// On native Windows, falls back to `USERPROFILE` when `HOME` is unset.
58|pub fn bot_home() -> PathBuf {
59|    if let Some(home) = HOME_OVERRIDE.with(|c| c.borrow().clone()) {
60|        return home;
61|    }
62|    match operator_home() {
63|        Ok(h) if !h.is_empty() => PathBuf::from(h),
64|        _ => PathBuf::from("."),
65|    }
66|}
67|
68|/// `$RS2B0T` when set and non-empty. A live [`IsolatedEnv`] starts cleared
69|/// so a unit test cannot inherit the operator catalog.
70|pub fn rs2b0t_env() -> Option<PathBuf> {
71|    match RS2B0T_OVERRIDE.with(|c| c.borrow().clone()) {
72|        Some(Rs2b0tOverride::Cleared) => return None,
73|        Some(Rs2b0tOverride::Set(p)) => return Some(p),
74|        None => {}
75|    }
76|    match std::env::var("RS2B0T") {
77|        Ok(v) if !v.is_empty() => Some(PathBuf::from(v)),
78|        _ => None,
79|    }
80|}
81|
82|/// `{bot_home()}/.274bot/{name}`.
83|pub fn bot_file(name: &str) -> PathBuf {
84|    bot_home().join(".274bot").join(name)
85|}
86|
87|/// Unique scratch `$HOME` (and optional `$RS2B0T`) for one test thread.
88|/// Drop restores the previous pin even on panic. Does **not** mutate the
89|/// process environment.
90|pub struct IsolatedEnv {
91|    pub dir: PathBuf,
92|    pub home: PathBuf,
93|    prev_home: Option<PathBuf>,
94|    prev_rs2b0t: Option<Rs2b0tOverride>,
95|}
96|
97|impl IsolatedEnv {
98|    /// Pin this thread's `~/.274bot` away from the operator home for the
99|    /// rest of the thread (cargo reuses test threads). Catalog tests that
100|    /// need a clean empty home still call [`IsolatedEnv::enter`].
101|    pub fn ensure_thread() {
102|        THREAD_PIN.with(|pin| {
103|            if pin.borrow().is_some() {
104|                restore_thread_pin();
105|                return;
106|            }
107|            let n = SEQ.fetch_add(1, Ordering::Relaxed);
108|            let dir = std::env::temp_dir().join(format!("274bot-test-thread-{n}"));
109|            let home = dir.join("home");
110|            let _ = std::fs::create_dir_all(&home);
111|            HOME_OVERRIDE.with(|c| {
112|                if c.borrow().is_none() {
113|                    *c.borrow_mut() = Some(home.clone());
114|                }
115|            });
116|            RS2B0T_OVERRIDE.with(|c| {
117|                if c.borrow().is_none() {
118|                    *c.borrow_mut() = Some(Rs2b0tOverride::Cleared);
119|                }
120|            });
121|            *pin.borrow_mut() = Some(home);
122|        });
123|    }
124|
125|    pub fn enter(label: &str) -> Self {
126|        let n = SEQ.fetch_add(1, Ordering::Relaxed);
127|        let dir = std::env::temp_dir().join(format!("274bot-iso-{label}-{n}"));
128|        let _ = std::fs::remove_dir_all(&dir);
129|        let home = dir.join("home");
130|        std::fs::create_dir_all(&home).unwrap();
131|        let prev_home = HOME_OVERRIDE.with(|c| c.borrow().clone());
132|        let prev_rs2b0t = RS2B0T_OVERRIDE.with(|c| c.borrow().clone());
133|        HOME_OVERRIDE.with(|c| *c.borrow_mut() = Some(home.clone()));
134|        RS2B0T_OVERRIDE.with(|c| *c.borrow_mut() = Some(Rs2b0tOverride::Cleared));
135|        Self {
136|            dir,
137|            home,
138|            prev_home,
139|            prev_rs2b0t,
140|        }
141|    }
142|
143|    pub fn set_rs2b0t(&self, root: &Path) {
144|        RS2B0T_OVERRIDE.with(|c| {
145|            *c.borrow_mut() = Some(Rs2b0tOverride::Set(root.to_path_buf()));
146|        });
147|    }
148|
149|    pub fn clear_rs2b0t(&self) {
150|        RS2B0T_OVERRIDE.with(|c| {
151|            *c.borrow_mut() = Some(Rs2b0tOverride::Cleared);
152|        });
153|    }
154|}
155|
156|impl Drop for IsolatedEnv {
157|    fn drop(&mut self) {
158|        HOME_OVERRIDE.with(|c| *c.borrow_mut() = self.prev_home.clone());
159|        RS2B0T_OVERRIDE.with(|c| *c.borrow_mut() = self.prev_rs2b0t.clone());
160|        restore_thread_pin();
161|        let _ = std::fs::remove_dir_all(&self.dir);
162|    }
163|}
164|
165|fn restore_thread_pin() {
166|    THREAD_PIN.with(|pin| {
167|        let Some(home) = pin.borrow().clone() else {
168|            return;
169|        };
170|        HOME_OVERRIDE.with(|c| {
171|            if c.borrow().is_none() {
172|                *c.borrow_mut() = Some(home);
173|            }
174|        });
175|        RS2B0T_OVERRIDE.with(|c| {
176|            if c.borrow().is_none() {
177|                *c.borrow_mut() = Some(Rs2b0tOverride::Cleared);
178|            }
179|        });
180|    });
