{"content": "1|//! Runtime world switch. Cargo's `TARGET` is the rustc triple.
2|//!
3|//! `BOT_TARGET=prod` (alias `live`) talks to `w1.rs2b2t.com` with the
4|//! baked public RSA. Anything else is the **local engine** on loopback.
5|//! Prod is HTTPS `/crc`+jags and WSS `ClientStream`; local stays TCP.
6|
7|use std::env;
8|use std::path::PathBuf;
9|use std::sync::OnceLock;
10|
11|/// Operator home for path defaults (`~/.274bot`, engine under `$HOME/...`).
12|///
13|/// Same `Result` shape as `env::var("HOME")`. On non-Windows this is
14|/// verbatim `HOME`. On Windows, an explicitly set `HOME` (including empty)
15|/// always wins; `USERPROFILE` is used only when `HOME` is absent or not
16|/// valid Unicode. Callers keep their own empty/fallback handling.
17|pub fn operator_home() -> Result<String, env::VarError> {
18|    operator_home_from(env::var("HOME"), || env::var("USERPROFILE"))
19|}
20|
21|/// Pure selector for tests: inject `HOME` / `USERPROFILE` results without
22|/// mutating the process environment.
23|fn operator_home_from(
24|    home: Result<String, env::VarError>,
25|    userprofile: impl FnOnce() -> Result<String, env::VarError>,
26|) -> Result<String, env::VarError> {
27|    #[cfg(windows)]
28|    {
29|        match home {
30|            Ok(h) => Ok(h),
31|            Err(_) => userprofile(),
32|        }
33|    }
34|    #[cfg(not(windows))]
35|    {
36|        let _ = userprofile;
37|        home
38|    }
39|}
40|
41|/// Which world a `Client` logs into.
42|#[derive(Debug, Clone, Copy, PartialEq, Eq)]
43|pub enum BotTarget {
44|    /// Loopback Lost City engine. Keys from `$ENGINE_DIR` / `LOGIN_RSAN`.
45|    Local,
46|    /// `w1.rs2b2t.com` with the baked public RSA.
47|    Prod,
48|}
49|
50|static OVERRIDE: OnceLock<BotTarget> = OnceLock::new();
51|
52|/// Parse `BOT_TARGET`. `prod` and `live` are the public world; unset/`local`
53|/// is the local engine.
54|pub fn bot_target_from_env(value: Option<&str>) -> BotTarget {
55|    match value {
56|        Some("prod") | Some("live") => BotTarget::Prod,
57|        _ => BotTarget::Local,
58|    }
59|}
60|
61|/// Process override (`--prod`). First call wins.
62|pub fn set_bot_target(target: BotTarget) {
63|    let _ = OVERRIDE.set(target);
64|}
65|
66|/// Active target: `--prod` override, else `BOT_TARGET`, else local.
67|pub fn bot_target() -> BotTarget {
68|    if let Some(t) = OVERRIDE.get() {
69|        return *t;
70|    }
71|    bot_target_from_env(env::var("BOT_TARGET").ok().as_deref())
72|}
73|
74|/// TCP host for a target.
75|pub fn world_host_for(target: BotTarget) -> &'static str {
76|    match target {
77|        BotTarget::Prod => "w1.rs2b2t.com",
78|        BotTarget::Local => "127.0.0.1",
79|    }
80|}
81|
82|/// Game port. Local is Java TCP `:43594`. Prod is WSS on `:443`.
83|pub fn game_port_for(target: BotTarget) -> u16 {
84|    match target {
85|        BotTarget::Prod => 443,
86|        BotTarget::Local => 43594,
87|    }
88|}
89|
90|/// Jag/crc fetch port. Local HTTP `:80`; Prod HTTPS `:443`.
91|pub fn jag_fetch_port_for(target: BotTarget) -> u16 {
92|    match target {
93|        BotTarget::Prod => 443,
94|        BotTarget::Local => 80,
95|    }
96|}
97|
98|/// Prod talks WSS + HTTPS; local stays TCP + HTTP.
99|pub fn uses_secure_transport(target: BotTarget) -> bool {
100|    target == BotTarget::Prod
101|}
102|
103|/// [`world_host_for`] for [`bot_target`].
104|pub fn world_host() -> String {
105|    world_host_for(bot_target()).into()
106|}
107|
108|/// Lost City engine root (`data/config/private.pem`, `data/pack/client`).
109|/// `$ENGINE_DIR` if set, else `$HOME/experiments/Server/engine`.
110|pub fn engine_dir() -> PathBuf {
111|    if let Ok(p) = env::var("ENGINE_DIR") {
112|        if !p.is_empty() {
113|            return PathBuf::from(p);
114|        }
115|    }
116|    match operator_home() {
117|        Ok(home) => PathBuf::from(home).join("experiments/Server/engine"),
118|        Err(_) => PathBuf::from("experiments/Server/engine"),
119|    }
120|}
