10|/// relative rs2b0t imports (`../../api/...`) resolve to the same shim
11|/// URLs no matter which script loaded; it is a synthetic specifier only
12|/// (nothing is read from `/rs2b0t` on this machine).
13|pub(crate) const BOT_MODULE: &str = "/rs2b0t/bot/scripts/bot/bot.js";
14|/// Canonical path of the shape wrapper that imports `./bot.js`.
15|pub(crate) const MAIN_MODULE: &str = "/rs2b0t/bot/scripts/bot/main.js";
16|
