25|// `performance`): elapsed ms since the isolate thread started, from the
26|// host-registered `__rs2b0t_now`. Execution delay/delayUntil use it.
27|globalThis.performance = {
28|    now: () => globalThis.rustyscript.functions.__rs2b0t_now(),
29|};
30|globalThis.defineBot = (manifest) => {
31|    if (!manifest || typeof manifest.name !== 'string' || manifest.name.length === 0 || typeof manifest.create !== 'function') {
32|        throw new Error('defineBot requires { name, create }');
33|    }
34|    return { __rs2b0tManifest: 1, ...manifest };
35|};
