1144|+impl Allocation {
1145|+    pub fn new(buffers: u64, textures: u64) -> Self {
1146|+        let (buffers, textures) = if ENABLED.load(Relaxed) {
1147|+            (buffers, textures)
1148|+        } else {
1149|+            (0, 0)
1150|+        };
1151|+        if buffers + textures > 0 {
1152|+            let mut g = GPU.lock().unwrap();
1153|+            g.buffers += buffers;
1154|+            g.textures += textures;
1155|+            g.peak = g.peak.max(g.buffers + g.textures);
