1169|+/// Count every mip and array layer; current formats have 4-byte texels
1170|+/// (including Depth32Float). Unknown format sizes fail visibly in profiling.
1171|+pub fn texture_bytes(t: &wgpu::Texture) -> u64 {
1172|+    if !ENABLED.load(Relaxed) {
1173|+        return 0;
1174|+    }
1175|+    let bytes = t
1176|+        .format()
1177|+        .block_copy_size(None)
1178|+        .expect("profile: texture format size");
1179|+    let (bw, bh) = t.format().block_dimensions();
1180|+    (0..t.mip_level_count())
1181|+        .map(|m| {
1182|+            let w = (t.width() >> m).max(1).div_ceil(bw) as u64;
1183|+            let h = (t.height() >> m).max(1).div_ceil(bh) as u64;
1184|+            let layers = if t.dimension() == wgpu::TextureDimension::D3 {
1185|+                (t.depth_or_array_layers() >> m).max(1)
1186|+            } else {
1187|+                t.depth_or_array_layers()
1188|+            };
1189|+            w * h * layers as u64 * bytes as u64 * t.sample_count() as u64
1190|+        })
1191|+        .sum()
