2|//! `~/.274bot/loadouts.json` (0o600). `optionsFrom: 'loadouts'` fills
3|//! setting combos from [`LoadoutsStore::names`].
4|
5|use std::path::PathBuf;
6|
7|use serde::{Deserialize, Serialize};
8|use vault::write_private_file;
9|
10|/// One named equipment/inventory preset.
11|#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
12|pub struct Loadout {
13|    pub name: String,
14|    pub worn: Vec<String>,
15|    pub carry: Vec<String>,
16|}
17|
18|/// Default operator loadouts path (`~/.274bot/loadouts.json`).
19|pub fn default_loadouts_path() -> PathBuf {
20|    crate::bot_file("loadouts.json")
21|}
22|
23|/// Persisted loadout list.
24|pub struct LoadoutsStore {
25|    path: PathBuf,
26|    loadouts: Vec<Loadout>,
27|    dirty: bool,
28|}
29|
30|impl LoadoutsStore {
31|    pub fn at(path: PathBuf) -> Self {
32|        let loadouts = std::fs::read_to_string(&path)
33|            .ok()
34|            .and_then(|raw| serde_json::from_str(&raw).ok())
35|            .unwrap_or_default();
36|        LoadoutsStore {
37|            path,
38|            loadouts,
39|            dirty: false,
40|        }
41|    }
42|
43|    pub fn with_default_path() -> Self {
44|        Self::at(default_loadouts_path())
45|    }
46|
47|    pub fn loadouts(&self) -> &[Loadout] {
48|        &self.loadouts
49|    }
50|
51|    pub fn names(&self) -> Vec<String> {
52|        self.loadouts.iter().map(|l| l.name.clone()).collect()
53|    }
54|
55|    pub fn get(&self, name: &str) -> Option<&Loadout> {
56|        self.loadouts.iter().find(|l| l.name == name)
57|    }
58|
59|    pub fn upsert(&mut self, loadout: Loadout) {
60|        self.dirty = true;
61|        if let Some(existing) = self.loadouts.iter_mut().find(|l| l.name == loadout.name) {
62|            *existing = loadout;
63|        } else {
64|            self.loadouts.push(loadout);
65|        }
66|    }
67|
68|    /// Replace the loadout at `index`, including renames (does not key on name).
69|    pub fn replace_at(&mut self, index: usize, loadout: Loadout) -> bool {
70|        if index >= self.loadouts.len() {
71|            return false;
72|        }
73|        self.dirty = true;
74|        self.loadouts[index] = loadout;
75|        true
76|    }
77|
78|    pub fn remove(&mut self, name: &str) -> bool {
79|        let before = self.loadouts.len();
80|        self.loadouts.retain(|l| l.name != name);
